// NestJS Logger Service using loglevel as the underlying provider
import { Injectable, LoggerService, Scope } from '@nestjs/common';
import { Logger } from 'loglevel';
import { 
    serviceLogger, 
    ipfsLogger, 
    orbitdbLogger, 
    replicationLogger, 
    healthLogger 
} from '../utils/logging.js';

@Injectable({ scope: Scope.TRANSIENT })
export class CustomLoggerService implements LoggerService {
    private logger: Logger;

    constructor(private context?: string) {
        // Map context to appropriate loglevel logger
        switch (context) {
            case 'IpfsClient':
                this.logger = ipfsLogger;
                break;
            case 'OrbitDBManager':
                this.logger = orbitdbLogger;
                break;
            case 'ReplicationHandler':
                this.logger = replicationLogger;
                break;
            case 'HealthCheckSystem':
                this.logger = healthLogger;
                break;
            default:
                this.logger = serviceLogger;
        }
    }

    log(message: string, context?: string): void {
        this.logger.info(this.formatMessage(message, context));
    }

    error(message: string, trace?: string, context?: string): void {
        this.logger.error(this.formatMessage(message, context), trace ? { trace } : undefined);
    }

    warn(message: string, context?: string): void {
        this.logger.warn(this.formatMessage(message, context));
    }

    debug(message: string, context?: string): void {
        this.logger.debug(this.formatMessage(message, context));
    }

    verbose(message: string, context?: string): void {
        this.logger.debug(this.formatMessage(message, context));
    }

    private formatMessage(message: string, context?: string): string {
        const ctx = context || this.context;
        return ctx ? `[${ctx}] ${message}` : message;
    }

    // Additional methods for structured logging
    info(message: string, meta?: Record<string, unknown>): void {
        this.logger.info(message, meta);
    }

    logWithMeta(level: 'info' | 'warn' | 'error' | 'debug', message: string, meta?: Record<string, unknown>): void {
        this.logger[level](message, meta);
    }

    // Method to get the underlying loglevel logger
    getLogger(): Logger {
        return this.logger;
    }
}

