// IPFS Kubo RPC client wrapper with connection management and error handling
import { create, type KuboRPCClient, CID } from 'kubo-rpc-client';
import { ipfsLogger } from '../utils/logging.js';
import { config } from '../config/environment.js';
import type {
    IPFSConnectionStatus,
    PinningRequest,
    PinningResult,
    IPFSRepositoryStats,
} from '../types/ipfs.js';

export class IpfsClient {
    private client: KuboRPCClient | null = null;
    private connectionStatus: IPFSConnectionStatus = {
        connected: false,
        lastCheck: 0,
    };

    constructor() {
        ipfsLogger.info('IPFS Kubo RPC Client initialized');
    }

    /**
     * Initialize connection to Kubo RPC API
     */
    async initialize(): Promise<void> {
        try {
            ipfsLogger.info(`🔗 Connecting to Kubo RPC API at ${config.ipfs.apiUrl}`);

            // Create client connection to Kubo
            this.client = create({ url: config.ipfs.apiUrl });

            // Test the connection
            await this.checkConnection();

            if (!this.connectionStatus.connected) {
                throw new Error('Failed to establish connection to Kubo RPC API');
            }

            ipfsLogger.info('✅ IPFS Kubo RPC Client connected successfully');
        } catch (error) {
            ipfsLogger.error('❌ Failed to initialize IPFS client', {
                error: error instanceof Error ? error.message : error,
                apiUrl: config.ipfs.apiUrl,
            });
            throw new Error('Failed to establish IPFS connection');
        }
    }

    /**
     * Check connection to Kubo node
     */
    async checkConnection(): Promise<boolean> {
        if (!this.client) {
            this.connectionStatus = {
                connected: false,
                lastCheck: Date.now(),
                error: 'Client not initialized',
            };
            return false;
        }

        try {
            // Test connection with id and version calls
            const [idResult, versionResult] = await Promise.all([
                this.client.id(),
                this.client.version()
            ]);

            this.connectionStatus = {
                connected: true,
                peerId: idResult.id.toString(),
                version: versionResult.version,
                lastCheck: Date.now(),
            };

            ipfsLogger.debug('✅ IPFS connection verified', {
                peerId: idResult.id.toString(),
                version: versionResult.version,
            });

            return true;
        } catch (error) {
            this.connectionStatus = {
                connected: false,
                lastCheck: Date.now(),
                error: error instanceof Error ? error.message : 'Unknown error',
            };

            ipfsLogger.error('❌ IPFS connection check failed', {
                error: error instanceof Error ? error.message : error,
                apiUrl: config.ipfs.apiUrl,
            });

            return false;
        }
    }

    /**
     * Pin content to IPFS node
     */
    async pinContent(request: PinningRequest): Promise<PinningResult> {
        const startTime = Date.now();

        try {
            if (!this.connectionStatus.connected) {
                await this.checkConnection();
                if (!this.connectionStatus.connected) {
                    throw new Error('IPFS client not connected');
                }
            }

            ipfsLogger.debug(`📌 Pinning content: ${request.cid}`, {
                cid: request.cid,
                recursive: request.recursive,
                clientIP: request.clientIP,
            });

            if (!this.client) {
                throw new Error('IPFS client not initialized');
            }

            const result = await this.client.pin.add(request.cid, {
                recursive: request.recursive
            });

            const duration = Date.now() - startTime;

            ipfsLogger.info(`✅ Content pinned successfully: ${request.cid}`, {
                cid: result.toString(),
                duration,
                recursive: request.recursive,
            });

            return {
                cid: result.toString(),
                success: true,
            };
        } catch (error) {
            const duration = Date.now() - startTime;

            ipfsLogger.error(`❌ Failed to pin content: ${request.cid}`, {
                error: error instanceof Error ? error.message : error,
                duration,
                cid: request.cid,
            });

            return {
                cid: request.cid,
                success: false,
                error: error instanceof Error ? error.message : 'Unknown error',
            };
        }
    }

    /**
     * Unpin content from IPFS node
     */
    async unpinContent(cid: string): Promise<boolean> {
        try {
            if (!this.connectionStatus.connected) {
                await this.checkConnection();
                if (!this.connectionStatus.connected) {
                    throw new Error('IPFS client not connected');
                }
            }

            ipfsLogger.debug(`📌 Unpinning content: ${cid}`);

            if (!this.client) {
                throw new Error('IPFS client not initialized');
            }

            await this.client.pin.rm(cid);

            ipfsLogger.info(`✅ Content unpinned successfully: ${cid}`, { cid });

            return true;
        } catch (error) {
            ipfsLogger.error(`❌ Failed to unpin content: ${cid}`, {
                error: error instanceof Error ? error.message : error,
                cid,
            });
            return false;
        }
    }

    /**
     * Get DAG content from IPFS
