     */
    getRawClient(): KuboRPCClient | null {
        return this.client;
    }

    /**
     * Get connection status
     */
    getConnectionStatus(): IPFSConnectionStatus {
        return this.connectionStatus;
    }

    /**
     * Graceful shutdown
     */
    async shutdown(): Promise<void> {
        try {
            ipfsLogger.info('🛑 Shutting down IPFS client');

            // Kubo RPC client doesn't need explicit shutdown
            this.client = null;
            this.connectionStatus = {
                connected: false,
                lastCheck: Date.now(),
            };

            ipfsLogger.info('✅ IPFS client shutdown complete');
        } catch (error) {
            ipfsLogger.error('Error during IPFS client shutdown', {
                error: error instanceof Error ? error.message : error,
            });
        }
    }
}

